// Simple Asteroid Escape game
// Canvas must have id="game"
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = canvas.offsetWidth;
  const H = canvas.height = canvas.offsetHeight;

  // Ship
  const ship = {x: W/2, y: H/2, r: 10, vx: 0, vy: 0, speed: 0.2, fuel: 100};
  const keys = {};

  // Entities
  const asteroids = [];
  const fuels = [];
  let score = 0;
  let lastTime = 0;
  let gameOver = false;

  // Helpers

input.oldString:
function draw() {
    ctx.clearRect(0,0,W,H);
    // ship
    ctx.fillStyle = '#0f0';
    ctx.beginPath(); ctx.arc(ship.x, ship.y, ship.r, 0, Math.PI*2); ctx.fill();
    // asteroids
    ctx.fillStyle = '#a33';
    asteroids.forEach(a => { ctx.beginPath(); ctx.arc(a.x, a.y, a.r, 0, Math.PI*2); ctx.fill(); });
    // fuel
    ctx.fillStyle = '#ff0';
    fuels.forEach(f => { ctx.beginPath(); ctx.arc(f.x, f.y, f.r, 0, Math.PI*2); ctx.fill(); });
    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '14px sans-serif';
    ctx.fillText(`Score: ${Math.floor(score)}`, 10, 20);
    ctx.fillText(`Fuel: ${Math.floor(ship.fuel)}`, 10, 40);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0,0,W,H);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', W/2, H/2);
    }
  }

input.newString:
function draw() {
    // Background starfield
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);
    for (let i = 0; i < stars.length; i++) {
      const s = stars[i];
      ctx.fillStyle = 'rgba(255,255,255,' + s.alpha + ')';
      ctx.fillRect(s.x, s.y, 1, 1);
    }

    // Ship (triangle oriented to movement)
    ctx.save();
    ctx.translate(ship.x, ship.y);
    const angle = Math.atan2(ship.vy, ship.vx) || 0;
    ctx.rotate(angle);
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.moveTo(ship.r, 0);
    ctx.lineTo(-ship.r, ship.r / 2);
    ctx.lineTo(-ship.r, -ship.r / 2);
    ctx.closePath();
    ctx.fill();
    ctx.restore();

    // Asteroids (simple polygon shapes)
    ctx.fillStyle = '#a33';
    asteroids.forEach(a => {
      ctx.save();
      ctx.translate(a.x, a.y);
      ctx.rotate(a.angle || 0);
      ctx.beginPath();
      const sides = 6 + Math.floor(Math.random() * 4);
      const step = (Math.PI * 2) / sides;
      for (let i = 0; i < sides; i++) {
        const rad = a.r * (0.7 + Math.random() * 0.3);
        ctx.lineTo(Math.cos(i * step) * rad, Math.sin(i * step) * rad);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    });

    // Fuel pickups (glowing radial gradient)
    fuels.forEach(f => {
      const grad = ctx.createRadialGradient(f.x, f.y, 0, f.x, f.y, f.r);
      grad.addColorStop(0, 'rgba(255,255,0,0.8)');
      grad.addColorStop(1, 'rgba(255,255,0,0.2)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
    });

    // HUD
    ctx.fillStyle = '#fff';
    ctx.font = '14px sans-serif';
    ctx.fillText(`Score: ${Math.floor(score)}`, 10, 20);
    ctx.fillText(`Fuel: ${Math.floor(ship.fuel)}`, 10, 40);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#fff';
      ctx.textAlign = 'center';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', W / 2, H / 2);
    }
  }

